-- Al-Fikr workbook implementation. No business seed records or automatic role grants.
begin;
insert into public.permissions(id,description) select m||'.'||a,'Al-Fikr '||m||' '||a from unnest(array['alfikr-sales','alfikr-marketing','alfikr-content']) m cross join unnest(array['read','write','delete']) a;
alter policy sales_read on public.products using(((public.has_permission('sales.read') or public.has_permission('products.read')) and business in ('Justech','Both')) or (public.has_permission('alfikr-sales.read') and business in ('Al-Fikr','Both')));
create function public.alfikr_reference_guard() returns trigger language plpgsql set search_path='' as $$declare item jsonb:=to_jsonb(new);begin
 if item->>'assigned_to' is not null and not exists(select 1 from public.employee_profiles where id=(item->>'assigned_to')::uuid and status='active') then raise exception 'Choose an active employee' using errcode='23514';end if;
 if item->>'account_id' is not null and not exists(select 1 from public.accounts where id=(item->>'account_id')::uuid and business in ('Al-Fikr','Both')) then raise exception 'Choose an Al-Fikr or shared institution' using errcode='23514';end if;
 if item->>'product_id' is not null and not exists(select 1 from public.products where id=(item->>'product_id')::uuid and business in ('Al-Fikr','Both')) then raise exception 'Choose an Al-Fikr or shared product' using errcode='23514';end if;return new;end $$;
revoke all on function public.alfikr_reference_guard() from public;
create table public.alfikr_sales_opportunities(id uuid primary key default gen_random_uuid(),name text not null check(length(name)<=250 and length(trim(name))>0),account_id uuid not null references public.accounts(id) on delete restrict,product_id uuid not null references public.products(id) on delete restrict,date date not null,due_date date,value numeric(15,3) check(value>=0),stage text not null check(stage in ('New','Qualified','Proposal','Negotiation','Won','Lost')),action_type text not null default '' check(length(action_type)<=250),expected_close date,notes text not null default '' check(length(notes)<=5000),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now() ,check(due_date is null or due_date>=date),check(expected_close is null or expected_close>=date));
alter table public.alfikr_sales_opportunities enable row level security;revoke all on public.alfikr_sales_opportunities from anon,authenticated;
grant select,delete on public.alfikr_sales_opportunities to authenticated;grant insert(name,account_id,product_id,date,due_date,value,stage,action_type,expected_close,notes,owner_id),update(name,account_id,product_id,date,due_date,value,stage,action_type,expected_close,notes) on public.alfikr_sales_opportunities to authenticated;
create policy module_read on public.alfikr_sales_opportunities for select to authenticated using(public.has_permission('alfikr-sales.read'));
create policy module_insert on public.alfikr_sales_opportunities for insert to authenticated with check(public.has_permission('alfikr-sales.write') and owner_id=(select auth.uid()) and public.team_record_write_allowed(null,owner_id));
create policy module_update on public.alfikr_sales_opportunities for update to authenticated using(public.has_permission('alfikr-sales.write') and public.team_record_write_allowed(null,owner_id)) with check(public.has_permission('alfikr-sales.write') and public.team_record_write_allowed(null,owner_id));
create policy module_delete on public.alfikr_sales_opportunities for delete to authenticated using(public.has_permission('alfikr-sales.delete') and public.team_record_write_allowed(null,owner_id));
create trigger revision before update on public.alfikr_sales_opportunities for each row execute function public.sales_touch_revision();
create trigger audit after insert or update or delete on public.alfikr_sales_opportunities for each row execute function public.audit_business_change();
create trigger references_check before insert or update on public.alfikr_sales_opportunities for each row execute function public.alfikr_reference_guard();
create view public.alfikr_sales_opportunities_list with(security_invoker=true) as select s.*,r0.name as account_id_label,r1.name as product_id_label,concat_ws(' ',s.name,s.date,s.due_date,s.value,s.stage,s.action_type,s.expected_close,s.notes,r0.name,r1.name) as search_text from public.alfikr_sales_opportunities s left join public.accounts r0 on r0.id=s.account_id left join public.products r1 on r1.id=s.product_id;grant select on public.alfikr_sales_opportunities_list to authenticated;
create table public.alfikr_sales_quotations(id uuid primary key default gen_random_uuid(),quotation_id text not null check(length(quotation_id)<=250 and length(trim(quotation_id))>0),account_id uuid not null references public.accounts(id) on delete restrict,product_id uuid not null references public.products(id) on delete restrict,subscription_period text not null default '' check(length(subscription_period)<=250),currency text not null check(currency is null or currency='' or currency ~ '^[A-Z]{3}$'),amount numeric(15,3) not null check(amount>=0),issue_date date not null,valid_until date not null,status text not null check(status in ('Draft','Pending','Accepted','Declined','Expired')),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,notes text not null default '' check(length(notes)<=5000),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now() ,check(valid_until>=issue_date));
create unique index alfikr_sales_quotations_quotation_id_idx on public.alfikr_sales_quotations(lower(quotation_id));
alter table public.alfikr_sales_quotations enable row level security;revoke all on public.alfikr_sales_quotations from anon,authenticated;
grant select,delete on public.alfikr_sales_quotations to authenticated;grant insert(quotation_id,account_id,product_id,subscription_period,currency,amount,issue_date,valid_until,status,assigned_to,notes,owner_id),update(quotation_id,account_id,product_id,subscription_period,currency,amount,issue_date,valid_until,status,assigned_to,notes) on public.alfikr_sales_quotations to authenticated;
create policy module_read on public.alfikr_sales_quotations for select to authenticated using(public.has_permission('alfikr-sales.read'));
create policy module_insert on public.alfikr_sales_quotations for insert to authenticated with check(public.has_permission('alfikr-sales.write') and owner_id=(select auth.uid()) and public.team_record_write_allowed(assigned_to,owner_id));
create policy module_update on public.alfikr_sales_quotations for update to authenticated using(public.has_permission('alfikr-sales.write') and public.team_record_write_allowed(assigned_to,owner_id)) with check(public.has_permission('alfikr-sales.write') and public.team_record_write_allowed(assigned_to,owner_id));
