create table public.alfikr_sales_subscriptions(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.accounts(id) on delete restrict,product_id uuid not null references public.products(id) on delete restrict,start_date date not null,end_date date not null,contract_duration text not null check(length(contract_duration)<=250 and length(trim(contract_duration))>0),status text not null check(status in ('Active','Confirmed','Upcoming','Expired','Cancelled')),annual_value numeric(15,3) check(annual_value>=0),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,notes text not null default '' check(length(notes)<=5000),currency text not null default '' check(currency is null or currency='' or currency ~ '^[A-Z]{3}$'),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now() ,check(end_date>=start_date),check(annual_value is null or currency ~ '^[A-Z]{3}$'),unique(account_id,product_id,start_date,end_date));
