grant select,delete on public.alfikr_sales_subscriptions to authenticated;grant insert(account_id,product_id,start_date,end_date,contract_duration,status,annual_value,assigned_to,notes,currency,owner_id),update(account_id,product_id,start_date,end_date,contract_duration,status,annual_value,assigned_to,notes,currency) on public.alfikr_sales_subscriptions to authenticated;
