create table public.alfikr_marketing_campaigns(id uuid primary key default gen_random_uuid(),name text not null check(length(name)<=250 and length(trim(name))>0),platform text not null check(length(platform)<=250 and length(trim(platform))>0),start_date date not null,end_date date not null,status text not null check(status in ('Planned','Active','On Hold','Completed','Cancelled')),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now() ,check(end_date>=start_date));
