create table public.alfikr_content_content_catalog(id uuid primary key default gen_random_uuid(),content_id text not null check(length(content_id)<=250 and length(trim(content_id))>0),title text not null check(length(title)<=250 and length(trim(title))>0),author text not null default '' check(length(author)<=250),publisher text not null default '' check(length(publisher)<=250),language text not null check(length(language)<=250 and length(trim(language))>0),content_type text not null check(content_type in ('Book','Journal','Article','Thesis','Other')),isbn text not null default '' check(length(isbn)<=250),category text not null default '' check(length(category)<=250),publication_year integer check(publication_year between 1 and 9999),file_link text check(file_link is null or file_link ~ '^https?://'),availability text not null check(availability in ('In Preparation','Awaiting Review','Published','Issues','Unavailable')),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,notes text not null default '' check(length(notes)<=5000),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz);
