create table public.alfikr_content_content_workflow(id uuid primary key default gen_random_uuid(),catalog_id uuid not null references public.alfikr_content_content_catalog(id) on delete restrict,publisher_source text not null default '' check(length(publisher_source)<=250),workflow_stage text not null check(workflow_stage in ('Received','Preparation','Review','Correction','Ready','Published')),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,date_received date not null,due_date date not null,review_result text not null check(review_result in ('Pending','Approved','Needs Changes','Rejected')),status text not null check(status in ('Active','On Hold','Completed','Cancelled')),notes text not null default '' check(length(notes)<=5000),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now() ,check(due_date>=date_received));
