create function public.alfikr_publish_time() returns trigger language plpgsql set search_path='' as $$begin if new.availability='Published' then if tg_op='INSERT' then new.published_at=now();elsif old.availability<>'Published' then new.published_at=now();else new.published_at=old.published_at;end if;else new.published_at=null;end if;return new;end $$;
revoke all on function public.alfikr_publish_time() from public;
create trigger published_time before insert or update on public.alfikr_content_content_catalog for each row execute function public.alfikr_publish_time();
create function public.create_alfikr_product(product_name text) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin
 if not public.has_permission('alfikr-sales.write') then raise exception 'Al-Fikr Sales write access required' using errcode='42501';end if;
 if length(trim(product_name)) not between 1 and 200 then raise exception 'Enter a product name';end if;
 insert into public.products(name,business,subscription_kind,owner_id) values(trim(product_name),'Al-Fikr','Other',auth.uid()) returning id into result;return result;end $$;
revoke all on function public.create_alfikr_product(text) from public;grant execute on function public.create_alfikr_product(text) to authenticated;
create function public.alfikr_overview(module text,as_of date default current_date,revenue_year integer default extract(year from current_date)::integer) returns jsonb language plpgsql stable security invoker set search_path='' as $$declare result jsonb;revenue jsonb;begin
 if module not in ('alfikr-sales','alfikr-marketing','alfikr-content') or not public.has_permission(module||'.read') then raise exception 'Al-Fikr read access required' using errcode='42501';end if;
 if module='alfikr-sales' then
 select coalesce(jsonb_object_agg(currency,total),'{}'::jsonb) into revenue from(select currency,sum(annual_value)::text total from(select distinct on(account_id,product_id) account_id,product_id,currency,annual_value from public.alfikr_sales_subscriptions where status in ('Active','Confirmed','Expired') and start_date<=make_date(revenue_year,12,31) and end_date>=make_date(revenue_year,1,1) order by account_id,product_id,start_date desc,end_date desc,id desc) t where annual_value is not null and currency ~ '^[A-Z]{3}$' group by currency) v;
 result=jsonb_build_object('Open Opportunities',(select count(*) from public.alfikr_sales_opportunities where stage not in ('Won','Lost')),'Pending Quotations',(select count(*) from public.alfikr_sales_quotations where status='Pending'),'Active Subscriptions',(select count(*) from public.alfikr_sales_subscriptions where status='Active' and start_date<=as_of and end_date>=as_of),'Upcoming Expirations',(select count(*) from public.alfikr_sales_subscriptions where status in ('Active','Confirmed') and end_date between as_of and as_of+90),'Annual Subscription Value',revenue,'Follow-ups Due',(select count(*) from public.alfikr_sales_opportunities where due_date<=as_of and stage not in ('Won','Lost')));
 elsif module='alfikr-marketing' then result=jsonb_build_object('Active Campaigns',(select count(*) from public.alfikr_marketing_campaigns where status='Active' and start_date<=as_of and end_date>=as_of),'Scheduled Content',(select count(*) from public.alfikr_marketing_content_calendar where status='Scheduled'),'Awaiting Approval',(select count(*) from public.alfikr_marketing_content_calendar where status='Awaiting Approval'),'Upcoming Campaigns',(select count(*) from public.alfikr_marketing_campaigns where start_date>as_of and start_date<=as_of+30 and status not in ('Cancelled','Completed')),'Published Content',(select count(*) from public.alfikr_marketing_content_calendar where status='Published'),'Overdue Content',(select count(*) from public.alfikr_marketing_content_calendar where publish_date<as_of and status not in ('Published','Cancelled')));
 else result=jsonb_build_object('Total Catalog Items',(select count(*) from public.alfikr_content_content_catalog),'Published Items',(select count(*) from public.alfikr_content_content_catalog where availability='Published'),'In Preparation',(select count(*) from public.alfikr_content_content_catalog where availability='In Preparation'),'Awaiting Review',(select count(*) from public.alfikr_content_content_catalog where availability='Awaiting Review'),'Items With Issues',(select count(*) from public.alfikr_content_content_catalog where availability='Issues'),'Recently Published',(select count(*) from public.alfikr_content_content_catalog where availability='Published' and published_at>=(as_of-30)::timestamptz));end if;return result;end $$;
revoke all on function public.alfikr_overview(text,date,integer) from public;grant execute on function public.alfikr_overview(text,date,integer) to authenticated;
commit;
